        return new Source("{% extends 'admin.html.twig' %}

{% block title %}Liste des utilisateurs{% endblock %}
{%block aa%}
{% endblock %}
{%block bb%}
{% endblock %}
{%block cc%}
{% endblock %}
{% block body %}
    <h1>Liste des utilisateurs</h1>

    <table class=\"table\">
        <thead>
            <tr>
                <th>Id</th>
                <th>Email</th>
                <th>Prénom</th>
                <th>Nom</th>
                <th>Rôles</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
        {% for user in users %}
            <tr>
                <td>{{ user.id }}</td>
                <td>{{ user.email }}</td>
                <td>{{ user.firstName }}</td>
                <td>{{ user.lastName }}</td>
                <td>{{ user.roles|join(', ') }}</td>
                <td>
                    <a href=\"{{ path('app_user_edit', {'id': user.id}) }}\" class=\"btn btn-warning\">Modifier</a>
                    <form method=\"post\" action=\"{{ path('app_user_delete', {'id': user.id}) }}\" style=\"display: inline-block;\">
                        <input type=\"hidden\" name=\"_token\" value=\"{{ csrf_token('delete' ~ user.id) }}\">
                        <button class=\"btn btn-danger\" onclick=\"return confirm('Êtes-vous sûr ?')\">Supprimer</button>
                    </form>
                </td>
            </tr>
        {% endfor %}
        </tbody>
    </table>
{% endblock %}", "user/index.html.twig", "C:\\Users\\Motaz\\mm Dropbox\\Motaz Sammoud\\PC\\Desktop\\hahaha\\symfony\\templates\\user\\index.html.twig");
